'use client'

import { useState, useEffect, FormEvent } from 'react'
import { Button, Select, TextArea, Card, CallStatusIndicator } from '@/components/ui'
import type { Store, CallPurpose, CallStatus } from '@/types'
import { CALL_PURPOSE_LABELS } from '@/types'

interface CallFormProps {
  onSubmit: (store: Store, purpose: CallPurpose, details: string) => void
  onHangUp: () => void
  callStatus: CallStatus
  isReady: boolean
  isInitializing: boolean
  onInitialize: () => void
}

export function CallForm({
  onSubmit,
  onHangUp,
  callStatus,
  isReady,
  isInitializing,
  onInitialize,
}: CallFormProps) {
  const [stores, setStores] = useState<Store[]>([])
  const [selectedStoreId, setSelectedStoreId] = useState('')
  const [purpose, setPurpose] = useState<CallPurpose>('product_inquiry')
  const [details, setDetails] = useState('')
  const [isLoadingStores, setIsLoadingStores] = useState(true)

  useEffect(() => {
    const fetchStores = async () => {
      try {
        const res = await fetch('/api/stores')
        const data = await res.json()
        setStores(data.stores)
      } catch (error) {
        console.error('Failed to fetch stores:', error)
      } finally {
        setIsLoadingStores(false)
      }
    }

    fetchStores()
  }, [])

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault()
    const store = stores.find((s) => s.id === selectedStoreId)
    if (store) {
      onSubmit(store, purpose, details)
    }
  }

  const purposeOptions = Object.entries(CALL_PURPOSE_LABELS).map(
    ([value, label]) => ({
      value,
      label,
    })
  )

  const storeOptions = stores.map((store) => ({
    value: store.id,
    label: store.name,
  }))

  const isInCall = callStatus === 'connecting' || callStatus === 'ringing' || callStatus === 'connected'

  return (
    <Card title="店舗に電話する">
      <div className="mb-4">
        <CallStatusIndicator status={callStatus} />
      </div>

      {!isReady ? (
        <div className="space-y-4">
          <p className="text-gray-600">
            電話機能を使用するには、まず初期化が必要です。
          </p>
          <Button
            onClick={onInitialize}
            isLoading={isInitializing}
            disabled={isInitializing}
          >
            電話機能を有効化
          </Button>
        </div>
      ) : isInCall ? (
        <div className="space-y-4">
          {callStatus === 'connected' && (
            <p className="text-green-600 font-medium">通話中です</p>
          )}
          <Button variant="danger" onClick={onHangUp} className="w-full">
            電話を切る
          </Button>
        </div>
      ) : (
        <form onSubmit={handleSubmit} className="space-y-4">
          <Select
            label="店舗を選択"
            options={storeOptions}
            value={selectedStoreId}
            onChange={(e) => setSelectedStoreId(e.target.value)}
            placeholder="店舗を選んでください"
            disabled={isLoadingStores}
            required
          />

          <Select
            label="お問い合わせ目的"
            options={purposeOptions}
            value={purpose}
            onChange={(e) => setPurpose(e.target.value as CallPurpose)}
            required
          />

          <TextArea
            label="詳細（任意）"
            value={details}
            onChange={(e) => setDetails(e.target.value)}
            placeholder="お問い合わせの詳細を入力してください"
            rows={3}
          />

          <Button
            type="submit"
            variant="success"
            className="w-full"
            disabled={!selectedStoreId}
          >
            電話をかける
          </Button>
        </form>
      )}
    </Card>
  )
}

