'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { CallForm } from '@/components/customer'
import { Button, Card } from '@/components/ui'
import { useCustomerCall } from '@/hooks'
import type { Store, CallPurpose } from '@/types'

export default function CustomerPhonePage() {
  const router = useRouter()
  const [isInitializing, setIsInitializing] = useState(false)

  const {
    callStatus,
    isReady,
    error,
    session,
    isLoading,
    initializeDevice,
    makeCall,
    hangUp,
  } = useCustomerCall()

  useEffect(() => {
    if (!isLoading && !session) {
      router.push('/login')
    }
  }, [isLoading, session, router])

  const handleInitialize = async () => {
    setIsInitializing(true)
    try {
      await initializeDevice()
    } catch (err) {
      console.error('Failed to initialize:', err)
    } finally {
      setIsInitializing(false)
    }
  }

  const handleCall = async (store: Store, purpose: CallPurpose, details: string) => {
    try {
      await makeCall(store, purpose, details)
    } catch (err) {
      console.error('Failed to make call:', err)
    }
  }

  const handleLogout = async () => {
    try {
      await fetch('/api/session/customer', { method: 'DELETE' })
      router.push('/login')
    } catch (err) {
      console.error('Failed to logout:', err)
    }
  }

  if (isLoading) {
    return (
      <div className="flex min-h-[50vh] items-center justify-center">
        <p className="text-gray-500">読み込み中...</p>
      </div>
    )
  }

  if (!session) {
    return null
  }

  return (
    <div className="space-y-4 py-4">
      <Card>
        <div className="flex items-center justify-between">
          <div>
            <p className="text-sm text-gray-500">ログイン中</p>
            <p className="font-semibold text-gray-900">{session.customerName}</p>
          </div>
          <Button variant="secondary" size="sm" onClick={handleLogout}>
            ログアウト
          </Button>
        </div>
      </Card>

      {error && (
        <div className="rounded-lg bg-red-50 p-4 text-red-700">
          {error}
        </div>
      )}

      <CallForm
        onSubmit={handleCall}
        onHangUp={hangUp}
        callStatus={callStatus}
        isReady={isReady}
        isInitializing={isInitializing}
        onInitialize={handleInitialize}
      />
    </div>
  )
}

