import twilio from 'twilio'

const VoiceResponse = twilio.twiml.VoiceResponse

interface DialClientParams {
  storeCode: string
  customerId: string
  customerName: string
  purpose: string
  details: string
}

export function createDialClientTwiml(params: DialClientParams): string {
  const response = new VoiceResponse()

  const dial = response.dial({
    callerId: 'client:customer-' + params.customerId,
  })

  dial.client(
    {
      statusCallbackEvent: ['initiated', 'ringing', 'answered', 'completed'],
    },
    `store-${params.storeCode}`
  )

  return response.toString()
}

export function createRejectTwiml(reason: string = 'busy'): string {
  const response = new VoiceResponse()
  response.reject({ reason: reason as 'busy' | 'rejected' })
  return response.toString()
}

import { NextRequest, NextResponse } from 'next/server'
import { createDialClientTwiml, createRejectTwiml } from '@/lib/twilio'

export async function POST(request: NextRequest) {
  try {
    const formData = await request.formData()

    const storeCode = formData.get('storeCode') as string
    const customerId = formData.get('customerId') as string
    const customerName = formData.get('customerName') as string
    const purpose = formData.get('purpose') as string
    const details = formData.get('details') as string

    if (!storeCode) {
      console.error('Missing storeCode in TwiML request')
      const twiml = createRejectTwiml('busy')
      return new NextResponse(twiml, {
        headers: { 'Content-Type': 'application/xml' },
      })
    }

    const twiml = createDialClientTwiml({
      storeCode,
      customerId: customerId || 'unknown',
      customerName: customerName || '不明',
      purpose: purpose || 'other',
      details: details || '',
    })

    return new NextResponse(twiml, {
      headers: { 'Content-Type': 'application/xml' },
    })
  } catch (error) {
    console.error('TwiML generation error:', error)
    const twiml = createRejectTwiml('busy')
    return new NextResponse(twiml, {
      headers: { 'Content-Type': 'application/xml' },
    })
  }
}

'use client'

import { useState, useCallback, useEffect } from 'react'
import { Call } from '@twilio/voice-sdk'
import { usePhoneDevice } from './usePhoneDevice'
import type { CallStatus, CallPurpose } from '@/types'

interface StaffSession {
  staffId: string
  staffName: string
  storeId: string
  storeCode: string
  storeName: string
}

interface IncomingCallInfo {
  customerId: string
  customerName: string
  purpose: CallPurpose
  details: string
}

interface UseStaffReceptionReturn {
  callStatus: CallStatus
  isReady: boolean
  error: string | null
  session: StaffSession | null
  isLoading: boolean
  incomingCallInfo: IncomingCallInfo | null
  initializeDevice: () => Promise<void>
  acceptCall: () => void
  rejectCall: () => void
  hangUp: () => void
}

export function useStaffReception(): UseStaffReceptionReturn {
  const [session, setSession] = useState<StaffSession | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [incomingCallInfo, setIncomingCallInfo] =
    useState<IncomingCallInfo | null>(null)

  const handleIncomingCall = useCallback((call: Call) => {
    const params = call.customParameters

    const info: IncomingCallInfo = {
      customerId: params.get('customerId') || 'unknown',
      customerName: params.get('customerName') || '不明',
      purpose: (params.get('purpose') as CallPurpose) || 'other',
      details: params.get('details') || '',
    }

    setIncomingCallInfo(info)
  }, [])

  const handleCallDisconnected = useCallback(() => {
    setIncomingCallInfo(null)
  }, [])

  const {
    callStatus,
    isReady,
    error,
    initialize,
    acceptCall: deviceAcceptCall,
    rejectCall: deviceRejectCall,
    hangUp: deviceHangUp,
  } = usePhoneDevice({
    onIncomingCall: handleIncomingCall,
    onCallDisconnected: handleCallDisconnected,
  })

  useEffect(() => {
    const fetchSession = async () => {
      try {
        const res = await fetch('/api/session/staff')
        const data = await res.json()
        if (data.session) {
          setSession(data.session)
        }
      } catch (err) {
        console.error('Failed to fetch session:', err)
      } finally {
        setIsLoading(false)
      }
    }

    fetchSession()
  }, [])

  const initializeDevice = useCallback(async () => {
    try {
      const res = await fetch('/api/token/staff', { method: 'POST' })
      const data = await res.json()

      if (!res.ok) {
        throw new Error(data.error || 'トークンの取得に失敗しました')
      }

      await initialize(data.token)
    } catch (err) {
      console.error('Failed to initialize device:', err)
      throw err
    }
  }, [initialize])

  const acceptCall = useCallback(() => {
    deviceAcceptCall()
  }, [deviceAcceptCall])

  const rejectCall = useCallback(() => {
    deviceRejectCall()
    setIncomingCallInfo(null)
  }, [deviceRejectCall])

  const hangUp = useCallback(() => {
    deviceHangUp()
    setIncomingCallInfo(null)
  }, [deviceHangUp])

  return {
    callStatus,
    isReady,
    error,
    session,
    isLoading,
    incomingCallInfo,
    initializeDevice,
    acceptCall,
    rejectCall,
    hangUp,
  }
}

