import { cookies } from 'next/headers'
import type { Customer, Staff } from '@/types'

const CUSTOMER_SESSION_KEY = 'customer_session'
const STAFF_SESSION_KEY = 'staff_session'

interface CustomerSession {
  customerId: string
  customerName: string
  email: string
  membershipNumber: string
}

interface StaffSession {
  staffId: string
  staffName: string
  storeId: string
  storeCode: string
  storeName: string
}

export async function setCustomerSession(customer: Customer): Promise<void> {
  const session: CustomerSession = {
    customerId: customer.id,
    customerName: customer.name,
    email: customer.email,
    membershipNumber: customer.membershipNumber,
  }

  const cookieStore = await cookies()
  cookieStore.set(CUSTOMER_SESSION_KEY, JSON.stringify(session), {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    maxAge: 60 * 60 * 24,
    path: '/',
  })
}

export async function getCustomerSession(): Promise<CustomerSession | null> {
  const cookieStore = await cookies()
  const sessionCookie = cookieStore.get(CUSTOMER_SESSION_KEY)

  if (!sessionCookie?.value) {
    return null
  }

  try {
    return JSON.parse(sessionCookie.value) as CustomerSession
  } catch {
    return null
  }
}

export async function clearCustomerSession(): Promise<void> {
  const cookieStore = await cookies()
  cookieStore.delete(CUSTOMER_SESSION_KEY)
}

export async function setStaffSession(
  staff: Staff,
  storeCode: string,
  storeName: string
): Promise<void> {
  const session: StaffSession = {
    staffId: staff.id,
    staffName: staff.name,
    storeId: staff.storeId,
    storeCode,
    storeName,
  }

  const cookieStore = await cookies()
  cookieStore.set(STAFF_SESSION_KEY, JSON.stringify(session), {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    maxAge: 60 * 60 * 24,
    path: '/',
  })
}

export async function getStaffSession(): Promise<StaffSession | null> {
  const cookieStore = await cookies()
  const sessionCookie = cookieStore.get(STAFF_SESSION_KEY)

  if (!sessionCookie?.value) {
    return null
  }

  try {
    return JSON.parse(sessionCookie.value) as StaffSession
  } catch {
    return null
  }
}

export async function clearStaffSession(): Promise<void> {
  const cookieStore = await cookies()
  cookieStore.delete(STAFF_SESSION_KEY)
}

export type { CustomerSession, StaffSession }

