import { NextRequest, NextResponse } from 'next/server'
import { validateDemoAuth, setDemoAuthSession, getDemoAuthSession } from '@/lib/auth'

export async function POST(request: NextRequest) {
  try {
    const body = await request.json()
    const { username, password } = body

    if (!username || !password) {
      return NextResponse.json(
        { error: 'ユーザー名とパスワードを入力してください' },
        { status: 400 }
      )
    }

    const isValid = await validateDemoAuth(username, password)

    if (!isValid) {
      return NextResponse.json(
        { error: '認証情報が正しくありません' },
        { status: 401 }
      )
    }

    await setDemoAuthSession()

    return NextResponse.json({ success: true })
  } catch (error) {
    console.error('Demo auth error:', error)
    return NextResponse.json(
      { error: '認証に失敗しました' },
      { status: 500 }
    )
  }
}

export async function GET() {
  try {
    const isAuthenticated = await getDemoAuthSession()
    return NextResponse.json({ authenticated: isAuthenticated })
  } catch (error) {
    console.error('Demo auth check error:', error)
    return NextResponse.json({ authenticated: false })
  }
}

