import type {
  TranscriptionMessage,
  TranscriptionSession,
} from '@/types/transcription'

type SSEController = ReadableStreamDefaultController<Uint8Array>

interface TranscriptionStore {
  sessions: Map<string, TranscriptionSession>
  subscribers: Map<string, Set<SSEController>>
}

const store: TranscriptionStore = {
  sessions: new Map(),
  subscribers: new Map(),
}

export function createSession(
  callSid: string,
  transcriptionSid: string
): TranscriptionSession {
  const session: TranscriptionSession = {
    callSid,
    transcriptionSid,
    messages: [],
    status: 'active',
    startedAt: Date.now(),
  }
  store.sessions.set(callSid, session)
  return session
}

export function getSession(callSid: string): TranscriptionSession | undefined {
  return store.sessions.get(callSid)
}

export function addMessage(
  callSid: string,
  message: TranscriptionMessage
): void {
  const session = store.sessions.get(callSid)
  if (!session) {
    return
  }

  const updatedMessages = [...session.messages, message]
  const updatedSession: TranscriptionSession = {
    ...session,
    messages: updatedMessages,
  }
  store.sessions.set(callSid, updatedSession)

  notifySubscribers(callSid, message)
}

export function updateMessageText(
  callSid: string,
  messageId: string,
  text: string,
  isFinal: boolean
): void {
  const session = store.sessions.get(callSid)
  if (!session) {
    return
  }

  const updatedMessages = session.messages.map((msg) =>
    msg.id === messageId ? { ...msg, text, isFinal } : msg
  )
  const updatedSession: TranscriptionSession = {
    ...session,
    messages: updatedMessages,
  }
  store.sessions.set(callSid, updatedSession)

  const updatedMessage = updatedMessages.find((msg) => msg.id === messageId)
  if (updatedMessage) {
    notifySubscribers(callSid, updatedMessage)
  }
}

export function endSession(callSid: string, status: 'stopped' | 'error'): void {
  const session = store.sessions.get(callSid)
  if (!session) {
    return
  }

  const updatedSession: TranscriptionSession = {
    ...session,
    status,
  }
  store.sessions.set(callSid, updatedSession)

  notifySubscribersEnd(callSid, status)
}

export function subscribe(callSid: string, controller: SSEController): void {
  const subscribers = store.subscribers.get(callSid) ?? new Set()
  subscribers.add(controller)
  store.subscribers.set(callSid, subscribers)
}

export function unsubscribe(callSid: string, controller: SSEController): void {
  const subscribers = store.subscribers.get(callSid)
  if (subscribers) {
    subscribers.delete(controller)
    if (subscribers.size === 0) {
      store.subscribers.delete(callSid)
    }
  }
}

function notifySubscribers(
  callSid: string,
  message: TranscriptionMessage
): void {
  const subscribers = store.subscribers.get(callSid)
  if (!subscribers) {
    return
  }

  const encoder = new TextEncoder()
  const data = `data: ${JSON.stringify({ type: 'message', data: message })}\n\n`

  subscribers.forEach((controller) => {
    try {
      controller.enqueue(encoder.encode(data))
    } catch {
      unsubscribe(callSid, controller)
    }
  })
}

function notifySubscribersEnd(
  callSid: string,
  status: 'stopped' | 'error'
): void {
  const subscribers = store.subscribers.get(callSid)
  if (!subscribers) {
    return
  }

  const encoder = new TextEncoder()
  const data = `data: ${JSON.stringify({ type: 'end', data: { status } })}\n\n`

  subscribers.forEach((controller) => {
    try {
      controller.enqueue(encoder.encode(data))
    } catch {
      // Controller already closed
    }
  })
}

export function cleanupOldSessions(maxAgeMs: number = 3600000): void {
  const now = Date.now()
  store.sessions.forEach((session, callSid) => {
    if (now - session.startedAt > maxAgeMs) {
      store.sessions.delete(callSid)
      store.subscribers.delete(callSid)
    }
  })
}

