import { NextRequest } from 'next/server'
import { subscribe, unsubscribe, getSession } from '@/lib/transcription/store'

export const dynamic = 'force-dynamic'

export async function GET(request: NextRequest): Promise<Response> {
  const searchParams = request.nextUrl.searchParams
  const callSid = searchParams.get('callSid')

  if (!callSid) {
    return new Response(JSON.stringify({ error: 'callSid is required' }), {
      status: 400,
      headers: { 'Content-Type': 'application/json' },
    })
  }

  const encoder = new TextEncoder()

  const stream = new ReadableStream<Uint8Array>({
    start(controller) {
      subscribe(callSid, controller)

      const session = getSession(callSid)
      if (session && session.messages.length > 0) {
        session.messages.forEach((message) => {
          const data = `data: ${JSON.stringify({ type: 'message', data: message })}\n\n`
          controller.enqueue(encoder.encode(data))
        })
      }

      const heartbeat = setInterval(() => {
        try {
          controller.enqueue(encoder.encode(': heartbeat\n\n'))
        } catch {
          clearInterval(heartbeat)
        }
      }, 30000)

      request.signal.addEventListener('abort', () => {
        clearInterval(heartbeat)
        unsubscribe(callSid, controller)
        try {
          controller.close()
        } catch {
          // Already closed
        }
      })
    },
  })

  return new Response(stream, {
    headers: {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache, no-transform',
      Connection: 'keep-alive',
      'X-Accel-Buffering': 'no',
    },
  })
}

