'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { CallForm } from '@/components/customer'
import { Button, Card } from '@/components/ui'
import { useCustomerCall } from '@/hooks'
import type { Store, CallPurpose } from '@/types'

export default function CustomerPhonePage() {
  const router = useRouter()
  const [isInitializing, setIsInitializing] = useState(false)

  const {
    callStatus,
    isReady,
    error,
    session,
    isLoading,
    initializeDevice,
    makeCall,
    hangUp,
  } = useCustomerCall()

  useEffect(() => {
    if (!isLoading && !session) {
      router.push('/customer/login')
    }
  }, [isLoading, session, router])

  const handleInitialize = async () => {
    setIsInitializing(true)
    try {
      await initializeDevice()
    } catch (err) {
      console.error('Failed to initialize:', err)
    } finally {
      setIsInitializing(false)
    }
  }

  const handleCall = async (store: Store, purpose: CallPurpose, details: string) => {
    try {
      await makeCall(store, purpose, details)
    } catch (err) {
      console.error('Failed to make call:', err)
    }
  }

  const handleLogout = async () => {
    try {
      await fetch('/api/session/customer', { method: 'DELETE' })
      router.push('/customer/login')
    } catch (err) {
      console.error('Failed to logout:', err)
    }
  }

  if (isLoading) {
    return (
      <div className="flex min-h-[50vh] items-center justify-center">
        <p className="text-gray-500">読み込み中...</p>
      </div>
    )
  }

  if (!session) {
    return null
  }

  return (
    <div className="space-y-4 py-4">
      <Card>
        <div className="flex items-center justify-between">
          <div>
            <p className="text-sm text-gray-500">ログイン中</p>
            <p className="font-semibold text-gray-900">{session.customerName}</p>
          </div>
          <Button variant="secondary" size="sm" onClick={handleLogout}>
            ログアウト
          </Button>
        </div>
      </Card>

      {error && (
        <div className="rounded-lg bg-red-50 p-4 text-red-700">
          {error}
        </div>
      )}

      <CallForm
        onSubmit={handleCall}
        onHangUp={hangUp}
        callStatus={callStatus}
        isReady={isReady}
        isInitializing={isInitializing}
        onInitialize={handleInitialize}
      />
    </div>
  )
}

'use client'

import { useState, useCallback, useEffect } from 'react'
import { usePhoneDevice } from './usePhoneDevice'
import type { CallParams, CallStatus, Store } from '@/types'

interface CustomerSession {
  customerId: string
  customerName: string
}

interface UseCustomerCallReturn {
  callStatus: CallStatus
  isReady: boolean
  error: string | null
  session: CustomerSession | null
  isLoading: boolean
  initializeDevice: () => Promise<void>
  makeCall: (store: Store, purpose: string, details: string) => Promise<void>
  hangUp: () => void
}

export function useCustomerCall(): UseCustomerCallReturn {
  const [session, setSession] = useState<CustomerSession | null>(null)
  const [isLoading, setIsLoading] = useState(true)

  const {
    callStatus,
    isReady,
    error,
    initialize,
    makeCall: deviceMakeCall,
    hangUp,
  } = usePhoneDevice()

  useEffect(() => {
    const fetchSession = async () => {
      try {
        const res = await fetch('/api/session/customer')
        const data = await res.json()
        if (data.session) {
          setSession({
            customerId: data.session.customerId,
            customerName: data.session.customerName,
          })
        }
      } catch (err) {
        console.error('Failed to fetch session:', err)
      } finally {
        setIsLoading(false)
      }
    }

    fetchSession()
  }, [])

  const initializeDevice = useCallback(async () => {
    try {
      const res = await fetch('/api/token/customer', { method: 'POST' })
      const data = await res.json()

      if (!res.ok) {
        throw new Error(data.error || 'トークンの取得に失敗しました')
      }

      await initialize(data.token)
    } catch (err) {
      console.error('Failed to initialize device:', err)
      throw err
    }
  }, [initialize])

  const makeCall = useCallback(
    async (store: Store, purpose: string, details: string) => {
      if (!session) {
        throw new Error('ログインが必要です')
      }

      const params: Record<string, string> = {
        storeCode: store.code,
        customerId: session.customerId,
        customerName: session.customerName,
        purpose,
        details,
      }

      await deviceMakeCall(params)
    },
    [session, deviceMakeCall]
  )

  return {
    callStatus,
    isReady,
    error,
    session,
    isLoading,
    initializeDevice,
    makeCall,
    hangUp,
  }
}

'use client'

import { useState, useCallback, useRef, useEffect } from 'react'
import { Device, Call } from '@twilio/voice-sdk'
import type { CallStatus } from '@/types'

interface UsePhoneDeviceOptions {
  onIncomingCall?: (call: Call) => void
  onCallConnected?: (call: Call) => void
  onCallDisconnected?: () => void
  onError?: (error: Error) => void
}

interface UsePhoneDeviceReturn {
  device: Device | null
  currentCall: Call | null
  callStatus: CallStatus
  isReady: boolean
  error: string | null
  initialize: (token: string) => Promise<void>
  makeCall: (params: Record<string, string>) => Promise<void>
  acceptCall: () => void
  rejectCall: () => void
  hangUp: () => void
  destroy: () => void
}

export function usePhoneDevice(
  options: UsePhoneDeviceOptions = {}
): UsePhoneDeviceReturn {
  const [device, setDevice] = useState<Device | null>(null)
  const [currentCall, setCurrentCall] = useState<Call | null>(null)
  const [callStatus, setCallStatus] = useState<CallStatus>('idle')
  const [isReady, setIsReady] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const deviceRef = useRef<Device | null>(null)
  const callRef = useRef<Call | null>(null)

  const { onIncomingCall, onCallConnected, onCallDisconnected, onError } =
    options

  const handleCallEvents = useCallback(
    (call: Call) => {
      call.on('accept', () => {
        setCallStatus('connected')
        onCallConnected?.(call)
      })

      call.on('disconnect', () => {
        setCallStatus('disconnected')
        setCurrentCall(null)
        callRef.current = null
        onCallDisconnected?.()
        setTimeout(() => setCallStatus('idle'), 1000)
      })

      call.on('cancel', () => {
        setCallStatus('idle')
        setCurrentCall(null)
        callRef.current = null
      })

      call.on('reject', () => {
        setCallStatus('idle')
        setCurrentCall(null)
        callRef.current = null
      })

      call.on('error', (callError) => {
        console.error('Call error:', callError)
        setError(callError.message)
        setCallStatus('idle')
        onError?.(callError)
      })
    },
    [onCallConnected, onCallDisconnected, onError]
  )

  const initialize = useCallback(
    async (token: string) => {
      try {
        setError(null)

        if (deviceRef.current) {
          deviceRef.current.destroy()
        }

        const newDevice = new Device(token, {
          codecPreferences: [Call.Codec.Opus, Call.Codec.PCMU],
          enableImprovedSignalingErrorPrecision: true,
        })

        newDevice.on('registered', () => {
          setIsReady(true)
        })

        newDevice.on('error', (deviceError) => {
          console.error('Device error:', deviceError)
          setError(deviceError.message)
          onError?.(deviceError)
        })

        newDevice.on('incoming', (incomingCall) => {
          setCurrentCall(incomingCall)
          callRef.current = incomingCall
          setCallStatus('ringing')
          handleCallEvents(incomingCall)
          onIncomingCall?.(incomingCall)
        })

        await newDevice.register()

        deviceRef.current = newDevice
        setDevice(newDevice)
      } catch (err) {
        const errorMessage =
          err instanceof Error ? err.message : 'デバイスの初期化に失敗しました'
        setError(errorMessage)
        onError?.(err instanceof Error ? err : new Error(errorMessage))
      }
    },
    [handleCallEvents, onIncomingCall, onError]
  )

  const makeCall = useCallback(
    async (params: Record<string, string>) => {
      if (!deviceRef.current) {
        setError('デバイスが初期化されていません')
        return
      }

      try {
        setError(null)
        setCallStatus('connecting')

        const call = await deviceRef.current.connect({ params })

        setCurrentCall(call)
        callRef.current = call
        setCallStatus('ringing')
        handleCallEvents(call)
      } catch (err) {
        const errorMessage =
          err instanceof Error ? err.message : '発信に失敗しました'
        setError(errorMessage)
        setCallStatus('idle')
        onError?.(err instanceof Error ? err : new Error(errorMessage))
      }
    },
    [handleCallEvents, onError]
  )

  const acceptCall = useCallback(() => {
    if (callRef.current) {
      callRef.current.accept()
      setCallStatus('connected')
    }
  }, [])

  const rejectCall = useCallback(() => {
    if (callRef.current) {
      callRef.current.reject()
      setCallStatus('idle')
      setCurrentCall(null)
      callRef.current = null
    }
  }, [])

  const hangUp = useCallback(() => {
    if (callRef.current) {
      callRef.current.disconnect()
      setCallStatus('disconnected')
      setCurrentCall(null)
      callRef.current = null
      setTimeout(() => setCallStatus('idle'), 1000)
    }
  }, [])

  const destroy = useCallback(() => {
    if (callRef.current) {
      callRef.current.disconnect()
    }
    if (deviceRef.current) {
      deviceRef.current.destroy()
    }
    setDevice(null)
    setCurrentCall(null)
    setCallStatus('idle')
    setIsReady(false)
    deviceRef.current = null
    callRef.current = null
  }, [])

  useEffect(() => {
    return () => {
      if (deviceRef.current) {
        deviceRef.current.destroy()
      }
    }
  }, [])

  return {
    device,
    currentCall,
    callStatus,
    isReady,
    error,
    initialize,
    makeCall,
    acceptCall,
    rejectCall,
    hangUp,
    destroy,
  }
}

