'use client'

import { useState, useCallback, useEffect } from 'react'
import { usePhoneDevice } from './usePhoneDevice'
import type { CallParams, CallStatus, Store } from '@/types'

interface CustomerSession {
  customerId: string
  customerName: string
}

interface UseCustomerCallReturn {
  callStatus: CallStatus
  isReady: boolean
  error: string | null
  session: CustomerSession | null
  isLoading: boolean
  initializeDevice: () => Promise<void>
  makeCall: (store: Store, purpose: string, details: string) => Promise<void>
  hangUp: () => void
}

export function useCustomerCall(): UseCustomerCallReturn {
  const [session, setSession] = useState<CustomerSession | null>(null)
  const [isLoading, setIsLoading] = useState(true)

  const {
    callStatus,
    isReady,
    error,
    initialize,
    makeCall: deviceMakeCall,
    hangUp,
  } = usePhoneDevice()

  useEffect(() => {
    const fetchSession = async () => {
      try {
        const res = await fetch('/api/session/customer')
        const data = await res.json()
        if (data.session) {
          setSession({
            customerId: data.session.customerId,
            customerName: data.session.customerName,
          })
        }
      } catch (err) {
        console.error('Failed to fetch session:', err)
      } finally {
        setIsLoading(false)
      }
    }

    fetchSession()
  }, [])

  const initializeDevice = useCallback(async () => {
    try {
      const res = await fetch('/api/token/customer', { method: 'POST' })
      const data = await res.json()

      if (!res.ok) {
        throw new Error(data.error || 'トークンの取得に失敗しました')
      }

      await initialize(data.token)
    } catch (err) {
      console.error('Failed to initialize device:', err)
      throw err
    }
  }, [initialize])

  const makeCall = useCallback(
    async (store: Store, purpose: string, details: string) => {
      if (!session) {
        throw new Error('ログインが必要です')
      }

      const params: Record<string, string> = {
        storeCode: store.code,
        customerId: session.customerId,
        customerName: session.customerName,
        purpose,
        details,
      }

      await deviceMakeCall(params)
    },
    [session, deviceMakeCall]
  )

  return {
    callStatus,
    isReady,
    error,
    session,
    isLoading,
    initializeDevice,
    makeCall,
    hangUp,
  }
}

