'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { ReceptionPanel } from '@/components/staff'
import { Button, Card } from '@/components/ui'
import { TranscriptionChat } from '@/components/transcription'
import { useStaffReception, useTranscription } from '@/hooks'

export default function StaffReceptionPage() {
  const router = useRouter()
  const [isInitializing, setIsInitializing] = useState(false)

  const {
    callStatus,
    callSid,
    isReady,
    error,
    session,
    isLoading,
    incomingCallInfo,
    initializeDevice,
    acceptCall,
    rejectCall,
    hangUp,
  } = useStaffReception()

  const {
    messages: transcriptionMessages,
    isConnected: isTranscriptionConnected,
    connect: connectTranscription,
    disconnect: disconnectTranscription,
    clearMessages,
  } = useTranscription()

  useEffect(() => {
    if (callStatus === 'connected' && callSid) {
      connectTranscription(callSid)
    } else if (callStatus === 'disconnected' || callStatus === 'idle') {
      disconnectTranscription()
    }
  }, [callStatus, callSid, connectTranscription, disconnectTranscription])

  useEffect(() => {
    if (!isLoading && !session) {
      router.push('/staff/login')
    }
  }, [isLoading, session, router])

  const handleInitialize = async () => {
    setIsInitializing(true)
    try {
      await initializeDevice()
    } catch {
      // Error is handled in the hook
    } finally {
      setIsInitializing(false)
    }
  }

  const handleAccept = () => {
    clearMessages()
    acceptCall()
  }

  const handleLogout = async () => {
    try {
      await fetch('/api/session/staff', { method: 'DELETE' })
      router.push('/staff/login')
    } catch {
      // Error is handled silently
    }
  }

  if (isLoading) {
    return (
      <div className="flex min-h-[50vh] items-center justify-center">
        <p className="text-gray-500">読み込み中...</p>
      </div>
    )
  }

  if (!session) {
    return null
  }

  const showTranscription = callStatus === 'connected'

  return (
    <div className="space-y-4 py-4">
      <Card>
        <div className="flex items-center justify-between">
          <div>
            <p className="text-sm text-gray-500">ログイン中</p>
            <p className="font-semibold text-gray-900">{session.staffName}</p>
          </div>
          <Button variant="secondary" size="sm" onClick={handleLogout}>
            ログアウト
          </Button>
        </div>
      </Card>

      {error && (
        <div className="rounded-lg bg-red-50 p-4 text-red-700">{error}</div>
      )}

      <ReceptionPanel
        storeName={session.storeName}
        callStatus={callStatus}
        isReady={isReady}
        isInitializing={isInitializing}
        incomingCallInfo={incomingCallInfo}
        onInitialize={handleInitialize}
        onAccept={handleAccept}
        onReject={rejectCall}
        onHangUp={hangUp}
      />

      {showTranscription && (
        <Card>
          <TranscriptionChat
            messages={transcriptionMessages}
            isCustomerView={false}
            isConnected={isTranscriptionConnected}
          />
        </Card>
      )}
    </div>
  )
}

