import { NextResponse } from 'next/server'
import { getCustomerSession } from '@/lib/auth'
import { generateAccessToken, generateCustomerIdentity } from '@/lib/twilio'

export async function POST() {
  try {
    const session = await getCustomerSession()

    if (!session) {
      return NextResponse.json(
        { error: 'ログインが必要です' },
        { status: 401 }
      )
    }

    const identity = generateCustomerIdentity(session.customerId)
    const token = generateAccessToken(identity)

    return NextResponse.json({
      token,
      identity,
    })
  } catch (error) {
    console.error('Token generation error:', error)
    return NextResponse.json(
      { error: 'トークンの生成に失敗しました' },
      { status: 500 }
    )
  }
}

import twilio from 'twilio'

const accountSid = process.env.TWILIO_ACCOUNT_SID
const authToken = process.env.TWILIO_AUTH_TOKEN
const apiKey = process.env.TWILIO_API_KEY
const apiSecret = process.env.TWILIO_API_SECRET
const twimlAppSid = process.env.TWILIO_TWIML_APP_SID

if (!accountSid || !authToken || !apiKey || !apiSecret || !twimlAppSid) {
  console.warn('Twilio environment variables are not fully configured')
}

export const twilioClient = twilio(accountSid, authToken)

export function generateAccessToken(identity: string): string {
  if (!accountSid || !apiKey || !apiSecret || !twimlAppSid) {
    throw new Error('Twilio environment variables are not configured')
  }

  const AccessToken = twilio.jwt.AccessToken
  const VoiceGrant = AccessToken.VoiceGrant

  const voiceGrant = new VoiceGrant({
    outgoingApplicationSid: twimlAppSid,
    incomingAllow: true,
  })

  const token = new AccessToken(accountSid, apiKey, apiSecret, {
    identity,
    ttl: 3600,
  })

  token.addGrant(voiceGrant)

  return token.toJwt()
}

export function generateCustomerIdentity(customerId: string): string {
  return `customer-${customerId}`
}

export function generateStoreIdentity(storeCode: string): string {
  return `store-${storeCode}`
}

'use client'

import { useState, useCallback, useRef, useEffect } from 'react'
import { Device, Call } from '@twilio/voice-sdk'
import type { CallStatus } from '@/types'

interface UsePhoneDeviceOptions {
  onIncomingCall?: (call: Call) => void
  onCallConnected?: (call: Call) => void
  onCallDisconnected?: () => void
  onError?: (error: Error) => void
}

interface UsePhoneDeviceReturn {
  device: Device | null
  currentCall: Call | null
  callSid: string | null
  callStatus: CallStatus
  isReady: boolean
  error: string | null
  initialize: (token: string) => Promise<void>
  makeCall: (params: Record<string, string>) => Promise<void>
  acceptCall: () => void
  rejectCall: () => void
  hangUp: () => void
  destroy: () => void
}

export function usePhoneDevice(
  options: UsePhoneDeviceOptions = {}
): UsePhoneDeviceReturn {
  const [device, setDevice] = useState<Device | null>(null)
  const [currentCall, setCurrentCall] = useState<Call | null>(null)
  const [callSid, setCallSid] = useState<string | null>(null)
  const [callStatus, setCallStatus] = useState<CallStatus>('idle')
  const [isReady, setIsReady] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const deviceRef = useRef<Device | null>(null)
  const callRef = useRef<Call | null>(null)

  const { onIncomingCall, onCallConnected, onCallDisconnected, onError } =
    options

  const handleCallEvents = useCallback(
    (call: Call) => {
      call.on('accept', () => {
        setCallStatus('connected')
        const sid = call.parameters?.CallSid || null
        setCallSid(sid)
        onCallConnected?.(call)
      })

      call.on('disconnect', () => {
        setCallStatus('disconnected')
        setCurrentCall(null)
        setCallSid(null)
        callRef.current = null
        onCallDisconnected?.()
        setTimeout(() => setCallStatus('idle'), 1000)
      })

      call.on('cancel', () => {
        setCallStatus('idle')
        setCurrentCall(null)
        setCallSid(null)
        callRef.current = null
      })

      call.on('reject', () => {
        setCallStatus('idle')
        setCurrentCall(null)
        setCallSid(null)
        callRef.current = null
      })

      call.on('error', (callError) => {
        console.error('Call error:', callError)
        setError(callError.message)
        setCallStatus('idle')
        onError?.(callError)
      })
    },
    [onCallConnected, onCallDisconnected, onError]
  )

  const initialize = useCallback(
    async (token: string) => {
      try {
        setError(null)

        if (deviceRef.current) {
          deviceRef.current.destroy()
        }

        const newDevice = new Device(token, {
          codecPreferences: [Call.Codec.Opus, Call.Codec.PCMU],
          enableImprovedSignalingErrorPrecision: true,
        })

        newDevice.on('registered', () => {
          setIsReady(true)
        })

        newDevice.on('error', (deviceError) => {
          console.error('Device error:', deviceError)
          setError(deviceError.message)
          onError?.(deviceError)
        })

        newDevice.on('incoming', (incomingCall) => {
          setCurrentCall(incomingCall)
          callRef.current = incomingCall
          setCallStatus('ringing')
          handleCallEvents(incomingCall)
          onIncomingCall?.(incomingCall)
        })

        await newDevice.register()

        deviceRef.current = newDevice
        setDevice(newDevice)
      } catch (err) {
        const errorMessage =
          err instanceof Error ? err.message : 'デバイスの初期化に失敗しました'
        setError(errorMessage)
        onError?.(err instanceof Error ? err : new Error(errorMessage))
      }
    },
    [handleCallEvents, onIncomingCall, onError]
  )

  const makeCall = useCallback(
    async (params: Record<string, string>) => {
      if (!deviceRef.current) {
        setError('デバイスが初期化されていません')
        return
      }

      try {
        setError(null)
        setCallStatus('connecting')

        const call = await deviceRef.current.connect({ params })

        setCurrentCall(call)
        callRef.current = call
        setCallStatus('ringing')
        handleCallEvents(call)
      } catch (err) {
        const errorMessage =
          err instanceof Error ? err.message : '発信に失敗しました'
        setError(errorMessage)
        setCallStatus('idle')
        onError?.(err instanceof Error ? err : new Error(errorMessage))
      }
    },
    [handleCallEvents, onError]
  )

  const acceptCall = useCallback(() => {
    if (callRef.current) {
      callRef.current.accept()
      setCallStatus('connected')
    }
  }, [])

  const rejectCall = useCallback(() => {
    if (callRef.current) {
      callRef.current.reject()
      setCallStatus('idle')
      setCurrentCall(null)
      callRef.current = null
    }
  }, [])

  const hangUp = useCallback(() => {
    if (callRef.current) {
      callRef.current.disconnect()
      setCallStatus('disconnected')
      setCurrentCall(null)
      callRef.current = null
      setTimeout(() => setCallStatus('idle'), 1000)
    }
  }, [])

  const destroy = useCallback(() => {
    if (callRef.current) {
      callRef.current.disconnect()
    }
    if (deviceRef.current) {
      deviceRef.current.destroy()
    }
    setDevice(null)
    setCurrentCall(null)
    setCallSid(null)
    setCallStatus('idle')
    setIsReady(false)
    deviceRef.current = null
    callRef.current = null
  }, [])

  useEffect(() => {
    return () => {
      if (deviceRef.current) {
        deviceRef.current.destroy()
      }
    }
  }, [])

  return {
    device,
    currentCall,
    callSid,
    callStatus,
    isReady,
    error,
    initialize,
    makeCall,
    acceptCall,
    rejectCall,
    hangUp,
    destroy,
  }
}

