import { NextRequest, NextResponse } from 'next/server'
import { v4 as uuidv4 } from 'uuid'
import {
  createSession,
  addMessage,
  updateMessageText,
  endSession,
  getSession,
} from '@/lib/transcription/store'
import type {
  TranscriptionTrack,
  TranscriptionMessage,
} from '@/types/transcription'

export async function POST(request: NextRequest): Promise<NextResponse> {
  try {
    const formData = await request.formData()
    const params = Object.fromEntries(formData.entries()) as Record<
      string,
      string
    >

    const callSid = params.CallSid
    const transcriptionSid = params.TranscriptionSid
    const status = params.TranscriptionStatus

    if (!callSid || !transcriptionSid) {
      return NextResponse.json(
        { error: 'Missing required parameters' },
        { status: 400 }
      )
    }

    switch (status) {
      case 'started':
        handleStarted(callSid, transcriptionSid)
        break

      case 'in-progress':
        handleContent(callSid, params)
        break

      case 'stopped':
        handleStopped(callSid)
        break

      case 'error':
        handleError(callSid, params.ErrorMessage)
        break

      default:
        break
    }

    return NextResponse.json({ success: true })
  } catch (error) {
    const errorMessage =
      error instanceof Error ? error.message : 'Unknown error'
    return NextResponse.json({ error: errorMessage }, { status: 500 })
  }
}

function handleStarted(callSid: string, transcriptionSid: string): void {
  createSession(callSid, transcriptionSid)
}

function handleContent(
  callSid: string,
  params: Record<string, string>
): void {
  const text = params.TranscriptionData
  const track = params.Track as TranscriptionTrack
  const isFinal = params.Final === 'true'
  const sequenceId = params.SequenceId

  if (!text || !track) {
    return
  }

  const session = getSession(callSid)
  if (!session) {
    return
  }

  const existingMessageIndex = session.messages.findIndex(
    (msg) => msg.id.startsWith(`${sequenceId}-${track}`) && !msg.isFinal
  )

  if (existingMessageIndex >= 0 && !isFinal) {
    const existingMessage = session.messages[existingMessageIndex]
    updateMessageText(callSid, existingMessage.id, text, isFinal)
  } else {
    const message: TranscriptionMessage = {
      id: `${sequenceId}-${track}-${uuidv4().slice(0, 8)}`,
      callSid,
      track,
      text,
      timestamp: Date.now(),
      isFinal,
    }
    addMessage(callSid, message)
  }
}

function handleStopped(callSid: string): void {
  endSession(callSid, 'stopped')
}

function handleError(callSid: string, errorMessage?: string): void {
  if (errorMessage) {
    // Could log the error here if needed
  }
  endSession(callSid, 'error')
}

