import { NextRequest } from 'next/server'
import { subscribe, unsubscribe, getSession } from '@/lib/transcription/store'

export const dynamic = 'force-dynamic'

export async function GET(request: NextRequest): Promise<Response> {
  const searchParams = request.nextUrl.searchParams
  const callSid = searchParams.get('callSid')

  if (!callSid) {
    return new Response(JSON.stringify({ error: 'callSid is required' }), {
      status: 400,
      headers: { 'Content-Type': 'application/json' },
    })
  }

  const encoder = new TextEncoder()

  const stream = new ReadableStream<Uint8Array>({
    start(controller) {
      subscribe(callSid, controller)

      const session = getSession(callSid)
      if (session && session.messages.length > 0) {
        session.messages.forEach((message) => {
          const data = `data: ${JSON.stringify({ type: 'message', data: message })}\n\n`
          controller.enqueue(encoder.encode(data))
        })
      }

      const heartbeat = setInterval(() => {
        try {
          controller.enqueue(encoder.encode(': heartbeat\n\n'))
        } catch {
          clearInterval(heartbeat)
        }
      }, 30000)

      request.signal.addEventListener('abort', () => {
        clearInterval(heartbeat)
        unsubscribe(callSid, controller)
        try {
          controller.close()
        } catch {
          // Already closed
        }
      })
    },
  })

  return new Response(stream, {
    headers: {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache, no-transform',
      Connection: 'keep-alive',
      'X-Accel-Buffering': 'no',
    },
  })
}

import { NextRequest, NextResponse } from 'next/server'
import { createDialClientTwiml, createRejectTwiml } from '@/lib/twilio'

function getBaseUrl(request: NextRequest): string {
  const forwardedHost = request.headers.get('x-forwarded-host')
  const forwardedProto = request.headers.get('x-forwarded-proto') || 'https'

  if (forwardedHost) {
    return `${forwardedProto}://${forwardedHost}`
  }

  const host = request.headers.get('host') || 'localhost:3000'
  const protocol = host.includes('localhost') ? 'http' : 'https'
  return `${protocol}://${host}`
}

export async function POST(request: NextRequest) {
  try {
    const formData = await request.formData()

    const storeCode = formData.get('storeCode') as string
    const customerId = formData.get('customerId') as string
    const customerName = formData.get('customerName') as string
    const purpose = formData.get('purpose') as string
    const details = formData.get('details') as string

    if (!storeCode) {
      const twiml = createRejectTwiml('busy')
      return new NextResponse(twiml, {
        headers: { 'Content-Type': 'application/xml' },
      })
    }

    const baseUrl = getBaseUrl(request)
    const transcriptionWebhookUrl = `${baseUrl}/api/transcription/webhook`

    const twiml = createDialClientTwiml({
      storeCode,
      customerId: customerId || 'unknown',
      customerName: customerName || '不明',
      purpose: purpose || 'other',
      details: details || '',
      transcriptionWebhookUrl,
    })

    return new NextResponse(twiml, {
      headers: { 'Content-Type': 'application/xml' },
    })
  } catch {
    const twiml = createRejectTwiml('busy')
    return new NextResponse(twiml, {
      headers: { 'Content-Type': 'application/xml' },
    })
  }
}

