  transcriptionSid: string
): TranscriptionSession {
  const session: TranscriptionSession = {
    callSid,
    transcriptionSid,
    messages: [],
    status: 'active',
    startedAt: Date.now(),
  }
  store.sessions.set(callSid, session)
  return session
}

export function getSession(callSid: string): TranscriptionSession | undefined {
  const directSession = store.sessions.get(callSid)
  if (directSession) {
    return directSession
  }

  const aliasedCallSid = store.callSidAliases.get(callSid)
  if (aliasedCallSid) {
    return store.sessions.get(aliasedCallSid)
  }

  return undefined
}

export function registerCallSidAlias(
  childCallSid: string,
  parentCallSid: string
): void {
  store.callSidAliases.set(childCallSid, parentCallSid)
}

export function addMessage(
  callSid: string,
  message: TranscriptionMessage
): void {
  const session = store.sessions.get(callSid)
  if (!session) {
    return
  }

  const updatedMessages = [...session.messages, message]
  const updatedSession: TranscriptionSession = {
    ...session,
    messages: updatedMessages,
  }
  store.sessions.set(callSid, updatedSession)

  notifySubscribers(callSid, message)
}

export function updateMessageText(
  callSid: string,
  messageId: string,
  text: string,
  isFinal: boolean
): void {
  const session = store.sessions.get(callSid)
  if (!session) {
    return
  }

  const updatedMessages = session.messages.map((msg) =>
    msg.id === messageId ? { ...msg, text, isFinal } : msg
  )
  const updatedSession: TranscriptionSession = {
    ...session,
    messages: updatedMessages,
  }
  store.sessions.set(callSid, updatedSession)

  const updatedMessage = updatedMessages.find((msg) => msg.id === messageId)
  if (updatedMessage) {
    notifySubscribers(callSid, updatedMessage)
  }
}

