'use client'

import { useState, useEffect } from 'react'
import { useRouter } from 'next/navigation'
import { CallForm } from '@/components/customer'
import { Button, Card } from '@/components/ui'
import { TranscriptionChat } from '@/components/transcription'
import { useCustomerCall, useTranscription } from '@/hooks'
import type { Store, CallPurpose } from '@/types'

export default function CustomerPhonePage() {
  const router = useRouter()
  const [isInitializing, setIsInitializing] = useState(false)

  const {
    callStatus,
    callSid,
    isReady,
    error,
    session,
    isLoading,
    initializeDevice,
    makeCall,
    hangUp,
  } = useCustomerCall()

  const {
    messages: transcriptionMessages,
    isConnected: isTranscriptionConnected,
    connect: connectTranscription,
    disconnect: disconnectTranscription,
    clearMessages,
  } = useTranscription()

  useEffect(() => {
    console.log('Call status changed:', { callStatus, callSid })
    if (callStatus === 'connected' && callSid) {
      console.log('Connecting transcription with callSid:', callSid)
      connectTranscription(callSid)
    } else if (callStatus === 'disconnected' || callStatus === 'idle') {
      disconnectTranscription()
    }
  }, [callStatus, callSid, connectTranscription, disconnectTranscription])

  useEffect(() => {
    if (!isLoading && !session) {
      router.push('/customer/login')
    }
  }, [isLoading, session, router])

  const handleInitialize = async () => {
    setIsInitializing(true)
    try {
      await initializeDevice()
    } catch {
      // Error is handled in the hook
    } finally {
      setIsInitializing(false)
    }
  }

  const handleCall = async (
    store: Store,
    purpose: CallPurpose,
    details: string
  ) => {
    clearMessages()
    try {
      await makeCall(store, purpose, details)
    } catch {
      // Error is handled in the hook
    }
  }

  const handleLogout = async () => {
    try {
      await fetch('/api/session/customer', { method: 'DELETE' })
      router.push('/customer/login')
    } catch {
      // Error is handled silently
    }
  }

  if (isLoading) {
    return (
      <div className="flex min-h-[50vh] items-center justify-center">
        <p className="text-gray-500">読み込み中...</p>
      </div>
    )
  }

  if (!session) {
    return null
  }

  const showTranscription =
    callStatus === 'connected' || callStatus === 'ringing'

  return (
    <div className="space-y-4 py-4">
      <Card>
        <div className="flex items-center justify-between">
          <div>
            <p className="text-sm text-gray-500">ログイン中</p>
            <p className="font-semibold text-gray-900">
              {session.customerName}
            </p>
          </div>
          <Button variant="secondary" size="sm" onClick={handleLogout}>
            ログアウト
          </Button>
        </div>
      </Card>

      {error && (
        <div className="rounded-lg bg-red-50 p-4 text-red-700">{error}</div>
      )}

      <CallForm
        onSubmit={handleCall}
        onHangUp={hangUp}
        callStatus={callStatus}
        isReady={isReady}
        isInitializing={isInitializing}
        onInitialize={handleInitialize}
      />

      {showTranscription && (
        <Card>
          <TranscriptionChat
            messages={transcriptionMessages}
            isCustomerView={true}
            isConnected={isTranscriptionConnected}
          />
        </Card>
      )}
    </div>
  )
}

