}

interface UseTranscriptionResult {
  messages: TranscriptionMessage[]
  isConnected: boolean
  error: string | null
  connect: (callSidOrSessionKey: string | SessionKeyParams) => void
  disconnect: () => void
  clearMessages: () => void
}

const POLL_INTERVAL = 500

export function useTranscription(): UseTranscriptionResult {
  const [messages, setMessages] = useState<TranscriptionMessage[]>([])
  const [isConnected, setIsConnected] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const pollingRef = useRef<NodeJS.Timeout | null>(null)
  const lastTimestampRef = useRef<number>(0)
  const connectionParamsRef = useRef<string | SessionKeyParams | null>(null)

  const fetchMessages = useCallback(async () => {
    const params = connectionParamsRef.current
    if (!params) return

    try {
      let url: string
      if (typeof params === 'string') {
        url = `/api/transcription/messages?callSid=${encodeURIComponent(params)}`
      } else {
        url = `/api/transcription/messages?customerId=${encodeURIComponent(params.customerId)}&storeCode=${encodeURIComponent(params.storeCode)}`
