'use client'

import { useState, useEffect, useCallback, useRef } from 'react'
import type { TranscriptionMessage } from '@/types/transcription'

interface SSEMessageEvent {
  type: 'message' | 'end'
  data: TranscriptionMessage | { status: 'stopped' | 'error' }
}

interface SessionKeyParams {
  customerId: string
  storeCode: string
}

interface UseTranscriptionResult {
  messages: TranscriptionMessage[]
  isConnected: boolean
  error: string | null
  connect: (callSidOrSessionKey: string | SessionKeyParams) => void
  disconnect: () => void
  clearMessages: () => void
}

export function useTranscription(): UseTranscriptionResult {
  const [messages, setMessages] = useState<TranscriptionMessage[]>([])
  const [isConnected, setIsConnected] = useState(false)
  const [error, setError] = useState<string | null>(null)
  const eventSourceRef = useRef<EventSource | null>(null)
  const callSidRef = useRef<string | null>(null)

  const disconnect = useCallback(() => {
    if (eventSourceRef.current) {
      eventSourceRef.current.close()
      eventSourceRef.current = null
    }
    setIsConnected(false)
    callSidRef.current = null
  }, [])

  const connect = useCallback(
    (callSidOrSessionKey: string | SessionKeyParams) => {
      if (eventSourceRef.current) {
        disconnect()
      }

      setError(null)
      setMessages([])

      let url: string
      if (typeof callSidOrSessionKey === 'string') {
        callSidRef.current = callSidOrSessionKey
        url = `/api/transcription/stream?callSid=${encodeURIComponent(callSidOrSessionKey)}`
      } else {
        callSidRef.current = `${callSidOrSessionKey.customerId}:${callSidOrSessionKey.storeCode}`
        url = `/api/transcription/stream?customerId=${encodeURIComponent(callSidOrSessionKey.customerId)}&storeCode=${encodeURIComponent(callSidOrSessionKey.storeCode)}`
      }

      const eventSource = new EventSource(url)

      eventSource.onopen = () => {
        setIsConnected(true)
      }

      eventSource.onmessage = (event) => {
        try {
          const parsed: SSEMessageEvent = JSON.parse(event.data)

          if (parsed.type === 'message') {
            const message = parsed.data as TranscriptionMessage
            setMessages((prev) => {
              const existingIndex = prev.findIndex(
                (m) => m.id === message.id
              )
              if (existingIndex >= 0) {
                return prev.map((m, i) =>
                  i === existingIndex ? message : m
                )
              }
              return [...prev, message]
            })
          } else if (parsed.type === 'end') {
            disconnect()
          }
        } catch {
          // Ignore parse errors (likely heartbeat)
        }
      }

      eventSource.onerror = () => {
        setError('文字起こし接続エラー')
        setIsConnected(false)
      }

      eventSourceRef.current = eventSource
    },
    [disconnect]
  )

  const clearMessages = useCallback(() => {
    setMessages([])
  }, [])

  useEffect(() => {
    return () => {
      disconnect()
    }
  }, [disconnect])

  return {
    messages,
    isConnected,
    error,
    connect,
    disconnect,
    clearMessages,
  }
}

