'use server'

import { Redis } from '@upstash/redis'
import type {
  TranscriptionMessage,
  TranscriptionSession,
} from '@/types/transcription'

const redis = new Redis({
  url: process.env.UPSTASH_REDIS_REST_URL || '',
  token: process.env.UPSTASH_REDIS_REST_TOKEN || '',
})

const SESSION_PREFIX = 'transcription:session:'
const SESSION_KEY_PREFIX = 'transcription:sessionkey:'
const SESSION_TTL = 3600

export async function createSession(
  callSid: string,
  transcriptionSid: string
): Promise<TranscriptionSession> {
  const session: TranscriptionSession = {
    callSid,
    transcriptionSid,
    messages: [],
    status: 'active',
    startedAt: Date.now(),
  }
  await redis.set(`${SESSION_PREFIX}${callSid}`, JSON.stringify(session), {
    ex: SESSION_TTL,
  })
  return session
}

export async function getSession(
  callSid: string
): Promise<TranscriptionSession | null> {
  const data = await redis.get<string>(`${SESSION_PREFIX}${callSid}`)
  if (!data) return null
  return typeof data === 'string' ? JSON.parse(data) : data
}

export async function addMessage(
  callSid: string,
  message: TranscriptionMessage
): Promise<void> {
  const session = await getSession(callSid)
  if (!session) return

  const updatedMessages = [...session.messages, message]
  const updatedSession: TranscriptionSession = {
    ...session,
    messages: updatedMessages,
  }
  await redis.set(
    `${SESSION_PREFIX}${callSid}`,
    JSON.stringify(updatedSession),
    { ex: SESSION_TTL }
  )
}

export async function updateMessageText(
  callSid: string,
  messageId: string,
  text: string,
  isFinal: boolean
): Promise<void> {
  const session = await getSession(callSid)
  if (!session) return

  const updatedMessages = session.messages.map((msg) =>
    msg.id === messageId ? { ...msg, text, isFinal } : msg
  )
  const updatedSession: TranscriptionSession = {
    ...session,
    messages: updatedMessages,
  }
  await redis.set(
    `${SESSION_PREFIX}${callSid}`,
    JSON.stringify(updatedSession),
    { ex: SESSION_TTL }
  )
}

export async function endSession(
  callSid: string,
  status: 'stopped' | 'error'
): Promise<void> {
  const session = await getSession(callSid)
  if (!session) return

  const updatedSession: TranscriptionSession = {
    ...session,
    status,
  }
  await redis.set(
    `${SESSION_PREFIX}${callSid}`,
    JSON.stringify(updatedSession),
    { ex: SESSION_TTL }
  )
}

export async function registerSessionKey(
  customerId: string,
  storeCode: string,
  callSid: string
): Promise<void> {
  const key = `${SESSION_KEY_PREFIX}${customerId}:${storeCode}`
  await redis.set(key, callSid, { ex: SESSION_TTL })
}

export async function getCallSidBySessionKey(
  customerId: string,
  storeCode: string
): Promise<string | null> {
  const key = `${SESSION_KEY_PREFIX}${customerId}:${storeCode}`
  return await redis.get<string>(key)
}

export async function getMessages(
  callSid: string,
  since?: number
): Promise<TranscriptionMessage[]> {
  const session = await getSession(callSid)
  if (!session) return []

  if (since) {
    return session.messages.filter((msg) => msg.timestamp > since)
  }
  return session.messages
}

