'use server'

import twilio from 'twilio'
import type {
  TranscriptionMessage,
  TranscriptionSession,
} from '@/types/transcription'

function getSyncClient() {
  const accountSid = process.env.TWILIO_ACCOUNT_SID
  const authToken = process.env.TWILIO_AUTH_TOKEN

  if (!accountSid || !authToken) {
    console.error('Twilio credentials not configured')
    return null
  }

  return twilio(accountSid, authToken)
}

async function getOrCreateSyncService(): Promise<string | null> {
  const client = getSyncClient()
  if (!client) return null

  const serviceSid = process.env.TWILIO_SYNC_SERVICE_SID

  if (serviceSid) {
    return serviceSid
  }

  try {
    const services = await client.sync.v1.services.list({ limit: 1 })
    if (services.length > 0) {
      return services[0].sid
    }

    const service = await client.sync.v1.services.create({
      friendlyName: 'UA-Webphone-Transcription',
    })
    console.log('Created Sync Service:', service.sid)
    return service.sid
  } catch (error) {
    console.error('Error getting/creating Sync Service:', error)
    return null
  }
}

const SESSION_PREFIX = 'transcription_'
const SESSION_KEY_PREFIX = 'sessionkey_'
const SESSION_TTL = 3600

export async function createSession(
  callSid: string,
  transcriptionSid: string
): Promise<TranscriptionSession | null> {
  const client = getSyncClient()
  const serviceSid = await getOrCreateSyncService()
  if (!client || !serviceSid) return null

  const session: TranscriptionSession = {
    callSid,
    transcriptionSid,
    messages: [],
    status: 'active',
    startedAt: Date.now(),
  }

  try {
    await client.sync.v1
      .services(serviceSid)
      .documents.create({
        uniqueName: `${SESSION_PREFIX}${callSid}`,
        data: session,
        ttl: SESSION_TTL,
      })
    return session
  } catch (error: unknown) {
    if (
      error &&
      typeof error === 'object' &&
      'code' in error &&
      error.code === 54301
    ) {
      return session
    }
    console.error('Error creating session:', error)
    return null
  }
}

