import { NextRequest, NextResponse } from 'next/server'
import { createDialClientTwiml, createRejectTwiml } from '@/lib/twilio'
import { registerSessionKey } from '@/lib/transcription/redis-store'

function getBaseUrl(request: NextRequest): string {
  const forwardedHost = request.headers.get('x-forwarded-host')
  const forwardedProto = request.headers.get('x-forwarded-proto') || 'https'

  if (forwardedHost) {
    return `${forwardedProto}://${forwardedHost}`
  }

  const host = request.headers.get('host') || 'localhost:3000'
  const protocol = host.includes('localhost') ? 'http' : 'https'
  return `${protocol}://${host}`
}

export async function POST(request: NextRequest) {
  try {
    const formData = await request.formData()

    const storeCode = formData.get('storeCode') as string
    const customerId = formData.get('customerId') as string
    const customerName = formData.get('customerName') as string
    const purpose = formData.get('purpose') as string
    const details = formData.get('details') as string
    const parentCallSid = formData.get('CallSid') as string

    if (!storeCode) {
      const twiml = createRejectTwiml('busy')
      return new NextResponse(twiml, {
        headers: { 'Content-Type': 'application/xml' },
      })
    }

    const baseUrl = getBaseUrl(request)
    const transcriptionWebhookUrl = `${baseUrl}/api/transcription/webhook`

    if (parentCallSid && customerId && storeCode) {
      await registerSessionKey(customerId, storeCode, parentCallSid)
    }

    const twiml = createDialClientTwiml({
      storeCode,
      customerId: customerId || 'unknown',
      customerName: customerName || '不明',
      purpose: purpose || 'other',
      details: details || '',
      transcriptionWebhookUrl,
      parentCallSid: parentCallSid || '',
    })

    return new NextResponse(twiml, {
      headers: { 'Content-Type': 'application/xml' },
    })
  } catch {
    const twiml = createRejectTwiml('busy')
