import { NextRequest, NextResponse } from 'next/server'
import {
  getMessages,
  getMessagesBySessionKey,
} from '@/lib/transcription/redis-store'

export const dynamic = 'force-dynamic'

export async function GET(request: NextRequest): Promise<NextResponse> {
  const searchParams = request.nextUrl.searchParams
  const callSid = searchParams.get('callSid')
  const customerId = searchParams.get('customerId')
  const storeCode = searchParams.get('storeCode')
  const since = searchParams.get('since')

  const sinceTimestamp = since ? parseInt(since, 10) : undefined

  if (callSid) {
    const messages = await getMessages(callSid, sinceTimestamp)
    return NextResponse.json({ messages, callSid })
  }

  if (customerId && storeCode) {
    const result = await getMessagesBySessionKey(
      customerId,
      storeCode,
      sinceTimestamp
    )
    return NextResponse.json(result)
  }

  return NextResponse.json(
    { error: 'callSid or customerId+storeCode is required' },
    { status: 400 }
  )
}

