'use server'

import twilio from 'twilio'
import type {
  TranscriptionMessage,
  TranscriptionSession,
} from '@/types/transcription'

function getSyncClient() {
  const accountSid = process.env.TWILIO_ACCOUNT_SID
  const authToken = process.env.TWILIO_AUTH_TOKEN

  if (!accountSid || !authToken) {
    console.error('Twilio credentials not configured')
    return null
  }

  return twilio(accountSid, authToken)
}

async function getOrCreateSyncService(): Promise<string | null> {
  const client = getSyncClient()
  if (!client) return null

  const serviceSid = process.env.TWILIO_SYNC_SERVICE_SID

  if (serviceSid) {
    return serviceSid
  }

  try {
    const services = await client.sync.v1.services.list({ limit: 1 })
    if (services.length > 0) {
      return services[0].sid
    }

    const service = await client.sync.v1.services.create({
      friendlyName: 'UA-Webphone-Transcription',
    })
    console.log('Created Sync Service:', service.sid)
    return service.sid
  } catch (error) {
    console.error('Error getting/creating Sync Service:', error)
    return null
  }
}

const SESSION_PREFIX = 'transcription_'
const SESSION_KEY_PREFIX = 'sessionkey_'
const SESSION_TTL = 3600

export async function createSession(
  callSid: string,
  transcriptionSid: string
): Promise<TranscriptionSession | null> {
  const client = getSyncClient()
  const serviceSid = await getOrCreateSyncService()
  if (!client || !serviceSid) return null

  const session: TranscriptionSession = {
    callSid,
    transcriptionSid,
    messages: [],
    status: 'active',
    startedAt: Date.now(),
  }

  try {
    await client.sync.v1
      .services(serviceSid)
      .documents.create({
        uniqueName: `${SESSION_PREFIX}${callSid}`,
        data: session,
        ttl: SESSION_TTL,
      })
    return session
  } catch (error: unknown) {
    if (
      error &&
      typeof error === 'object' &&
      'code' in error &&
      error.code === 54301
    ) {
      return session
    }
    console.error('Error creating session:', error)
    return null
  }
}

export async function getSession(
  callSid: string
): Promise<TranscriptionSession | null> {
  const client = getSyncClient()
  const serviceSid = await getOrCreateSyncService()
  if (!client || !serviceSid) return null

  try {
    const doc = await client.sync.v1
      .services(serviceSid)
      .documents(`${SESSION_PREFIX}${callSid}`)
      .fetch()
    return doc.data as TranscriptionSession
  } catch (error: unknown) {
    if (
      error &&
      typeof error === 'object' &&
      'status' in error &&
      error.status === 404
    ) {
      return null
    }
    console.error('Error getting session:', error)
    return null
  }
}

export async function addMessage(
  callSid: string,
  message: TranscriptionMessage
): Promise<void> {
  const client = getSyncClient()
  const serviceSid = await getOrCreateSyncService()
  if (!client || !serviceSid) return

  const session = await getSession(callSid)
  if (!session) return

  const updatedMessages = [...session.messages, message]
  const updatedSession: TranscriptionSession = {
    ...session,
    messages: updatedMessages,
  }

  try {
    await client.sync.v1
      .services(serviceSid)
      .documents(`${SESSION_PREFIX}${callSid}`)
      .update({ data: updatedSession, ttl: SESSION_TTL })
  } catch (error) {
    console.error('Error adding message:', error)
  }
}

export async function updateMessageText(
  callSid: string,
  messageId: string,
  text: string,
  isFinal: boolean
): Promise<void> {
  const client = getSyncClient()
  const serviceSid = await getOrCreateSyncService()
  if (!client || !serviceSid) return

  const session = await getSession(callSid)
  if (!session) return

  const updatedMessages = session.messages.map((msg) =>
    msg.id === messageId ? { ...msg, text, isFinal } : msg
  )
  const updatedSession: TranscriptionSession = {
    ...session,
    messages: updatedMessages,
  }

  try {
    await client.sync.v1
      .services(serviceSid)
      .documents(`${SESSION_PREFIX}${callSid}`)
      .update({ data: updatedSession, ttl: SESSION_TTL })
  } catch (error) {
    console.error('Error updating message:', error)
  }
}

export async function endSession(
  callSid: string,
  status: 'stopped' | 'error'
): Promise<void> {
  const client = getSyncClient()
  const serviceSid = await getOrCreateSyncService()
  if (!client || !serviceSid) return

  const session = await getSession(callSid)
  if (!session) return

  const updatedSession: TranscriptionSession = {
    ...session,
    status,
  }

  try {
    await client.sync.v1
      .services(serviceSid)
      .documents(`${SESSION_PREFIX}${callSid}`)
      .update({ data: updatedSession, ttl: SESSION_TTL })
  } catch (error) {
    console.error('Error ending session:', error)
  }
}

export async function registerSessionKey(
  customerId: string,
  storeCode: string,
  callSid: string
): Promise<void> {
  const client = getSyncClient()
  const serviceSid = await getOrCreateSyncService()
  if (!client || !serviceSid) return

  const key = `${customerId}_${storeCode}`.replace(/[^a-zA-Z0-9_-]/g, '_')

  try {
    await client.sync.v1
      .services(serviceSid)
      .documents.create({
        uniqueName: `${SESSION_KEY_PREFIX}${key}`,
        data: { callSid },
        ttl: SESSION_TTL,
      })
  } catch (error: unknown) {
    if (
      error &&
      typeof error === 'object' &&
      'code' in error &&
      error.code === 54301
    ) {
      await client.sync.v1
        .services(serviceSid)
        .documents(`${SESSION_KEY_PREFIX}${key}`)
        .update({ data: { callSid }, ttl: SESSION_TTL })
    } else {
      console.error('Error registering session key:', error)
    }
  }
}

export async function getCallSidBySessionKey(
  customerId: string,
  storeCode: string
): Promise<string | null> {
  const client = getSyncClient()
  const serviceSid = await getOrCreateSyncService()
  if (!client || !serviceSid) return null

  const key = `${customerId}_${storeCode}`.replace(/[^a-zA-Z0-9_-]/g, '_')

  try {
    const doc = await client.sync.v1
      .services(serviceSid)
      .documents(`${SESSION_KEY_PREFIX}${key}`)
      .fetch()
    return (doc.data as { callSid: string }).callSid
  } catch (error: unknown) {
    if (
      error &&
      typeof error === 'object' &&
      'status' in error &&
      error.status === 404
    ) {
      return null
    }
    console.error('Error getting session key:', error)
    return null
  }
}

export async function getMessages(
  callSid: string,
  since?: number
): Promise<TranscriptionMessage[]> {
  const session = await getSession(callSid)
  if (!session) return []

  if (since) {
    return session.messages.filter((msg) => msg.timestamp > since)
  }
  return session.messages
}

export async function getMessagesBySessionKey(
  customerId: string,
  storeCode: string,
  since?: number
): Promise<{ messages: TranscriptionMessage[]; callSid: string | null }> {
  const callSid = await getCallSidBySessionKey(customerId, storeCode)
  if (!callSid) return { messages: [], callSid: null }

  const messages = await getMessages(callSid, since)
  return { messages, callSid }
}

