              },
              {
                "id": "GTccef72e293cbf6e05490cf9efa485358",
                "participantSid": "unknown",
                "sequenceId": "5",
                "text": " トイレの場所教えてください。",
                "timestamp": "2025-07-12T13:00:36.845Z",
                "track": "outbound_track"
              },
              {
                "id": "GTccef72e293cbf6e05490cf9efa485358",
                "participantSid": "unknown",
                "sequenceId": "6",
                "text": "ありがとうございます。",
                "timestamp": "2025-07-12T13:00:45.435Z",
                "track": "outbound_track"
              },
              {
                "id": "GTccef72e293cbf6e05490cf9efa485358",
                "participantSid": "unknown",
                "sequenceId": "7",
                "text": "昨日の行った本屋さんてどこ？",
                "timestamp": "2025-07-12T13:00:56.480Z",
                "track": "outbound_track"
              },
              {
                "id": "GTccef72e293cbf6e05490cf9efa485358",
                "participantSid": "unknown",
                "sequenceId": "8",
                "text": " こんにちは。英語を日本語に翻訳する通訳です。英語でお話しいただければ 日本で翻訳します。",
                "timestamp": "2025-07-12T13:01:25.477Z",
                "track": "outbound_track"
              },
              {
                "id": "GTccef72e293cbf6e05490cf9efa485358",
                "participantSid": "unknown",
                "sequenceId": "9",
                "text": "how。",
