// This function starts realtime transcription for a call
exports.handler = async function(context, event, callback) {
    try {
        const client = context.getTwilioClient();
        const { callSid } = event;

        if (!callSid) {
            return callback(null, {
                success: false,
                error: 'callSid is required'
            });
        }

        // Start realtime transcription using the correct API
        // The API might be different - let's try the REST API approach
        const transcription = await fetch(`https://api.twilio.com/2010-04-01/Accounts/${context.ACCOUNT_SID}/Calls/${callSid}/Transcriptions.json`, {
            method: 'POST',
            headers: {
                'Authorization': `Basic ${Buffer.from(`${context.ACCOUNT_SID}:${context.AUTH_TOKEN}`).toString('base64')}`,
                'Content-Type': 'application/x-www-form-urlencoded'
            },
            body: new URLSearchParams({
                Track: 'both_tracks',
                LanguageCode: 'ja-JP', 
                PartialResults: 'false',
                ProfanityFilter: 'false',
                StatusCallbackUrl: `https://${context.DOMAIN_NAME}/transcription-webhook`,
                StatusCallbackMethod: 'POST'
            }).toString()
        });

        const result = await transcription.json();

        if (!transcription.ok) {
            throw new Error(`Transcription API error: ${result.message || transcription.statusText}`);
        }

        console.log('Transcription started:', result.sid);

        return callback(null, {
            success: true,
            message: 'Transcription started',
            transcriptionSid: result.sid,
            callSid: callSid
        });

    } catch (error) {
        console.error('Error starting transcription:', error);
        return callback(error);
    }
};

