exports.handler = async function(context, event, callback) {
    console.log('Transcription webhook received:', JSON.stringify(event));

    try {
        const syncServiceSid = context.SYNC_SERVICE_SID;
        if (!syncServiceSid) {
            throw new Error('SYNC_SERVICE_SID not configured');
        }

        const sync = context.getTwilioClient().sync.services(syncServiceSid);

        // Extract transcription data from event
        // Realtime transcription sends different fields
        const {
            ConferenceSid,
            CallSid,
            TranscriptionText,
            TranscriptionSid,
            SequenceId,
            Track,
            ParticipantSid,
            TranscriptionEvent,
            // Additional fields from realtime transcription
            transcriptionText,
            transcriptionData,
            trackLabel
        } = event;

        // Handle both formats
        let text = TranscriptionText || transcriptionText;

        // Parse TranscriptionData if it exists
        if (!text && event.TranscriptionData) {
            try {
                const parsedData = JSON.parse(event.TranscriptionData);
                text = parsedData.transcript;
            } catch (e) {
                console.log('Failed to parse TranscriptionData:', e.message);
            }
        }

        // Fallback to transcriptionData object
        if (!text && transcriptionData && transcriptionData.transcript) {
            text = transcriptionData.transcript;
        }

        // Use ConferenceSid or CallSid for document name
        const conferenceId = ConferenceSid || CallSid;

        // Skip events that don't have text (like transcription-started)
        if (TranscriptionEvent === 'transcription-started') {
            console.log('Transcription started event - no text to process');
            return callback(null, { success: true, message: 'Transcription started' });
        }

        if (!conferenceId || !text) {
            console.log('Missing required fields - conferenceId:', conferenceId, 'text:', text);
            console.log('Event:', JSON.stringify(event));
            return callback(null, { success: false, error: 'Missing required fields' });
        }

        const documentName = `transcription_${conferenceId}`;

        // Create new transcription entry
        const transcriptionEntry = {
            id: TranscriptionSid || Date.now().toString(),
            text: text,
            timestamp: new Date().toISOString(),
            sequenceId: SequenceId || parseInt(SequenceId) || Date.now(),
            track: Track || trackLabel || 'unknown',
            participantSid: ParticipantSid || 'unknown'
        };

        try {
            // Try to update existing document
            const doc = await sync.documents(documentName).fetch();
            const currentData = doc.data || { transcripts: [] };
            currentData.transcripts.push(transcriptionEntry);
            currentData.lastUpdated = new Date().toISOString();

            await sync.documents(documentName).update({ data: currentData });
            console.log('Updated existing transcription document');
        } catch (fetchError) {
            // Document doesn't exist, create new one
            if (fetchError.status === 404) {
                await sync.documents.create({
                    uniqueName: documentName,
                    data: {
                        conferenceSid: conferenceId,
                        transcripts: [transcriptionEntry],
                        startTime: new Date().toISOString(),
                        lastUpdated: new Date().toISOString()
                    }
                });
                console.log('Created new transcription document');
            } else {
                throw fetchError;
            }
        }

        return callback(null, { success: true });

    } catch (error) {
        console.error('Transcription webhook error:', error);
        return callback(error);
    }
};

