import { NextRequest, NextResponse } from 'next/server'

export async function POST(request: NextRequest): Promise<NextResponse> {
  try {
    const { callSid } = await request.json()

    if (!callSid) {
      return NextResponse.json(
        { error: 'callSid is required' },
        { status: 400 }
      )
    }

    const accountSid = process.env.TWILIO_ACCOUNT_SID
    const authToken = process.env.TWILIO_AUTH_TOKEN

    if (!accountSid || !authToken) {
      return NextResponse.json(
        { error: 'Twilio credentials not configured' },
        { status: 500 }
      )
    }

    const baseUrl = request.headers.get('x-forwarded-host')
      ? `https://${request.headers.get('x-forwarded-host')}`
      : `https://${request.headers.get('host')}`

    const webhookUrl = `${baseUrl}/api/transcription/webhook`

    console.log('Starting transcription for call:', callSid)
    console.log('Webhook URL:', webhookUrl)

    const response = await fetch(
      `https://api.twilio.com/2010-04-01/Accounts/${accountSid}/Calls/${callSid}/Transcriptions.json`,
      {
        method: 'POST',
        headers: {
          Authorization: `Basic ${Buffer.from(`${accountSid}:${authToken}`).toString('base64')}`,
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: new URLSearchParams({
          Track: 'both_tracks',
          LanguageCode: 'ja-JP',
          PartialResults: 'true',
          ProfanityFilter: 'false',
          StatusCallbackUrl: webhookUrl,
          StatusCallbackMethod: 'POST',
        }).toString(),
      }
    )

    const result = await response.json()

    if (!response.ok) {
      console.error('Transcription API error:', result)
      return NextResponse.json(
        { error: result.message || 'Failed to start transcription' },
        { status: response.status }
      )
    }

    console.log('Transcription started:', result.sid)

    return NextResponse.json({
      success: true,
      transcriptionSid: result.sid,
      callSid,
    })
  } catch (error) {
    console.error('Error starting transcription:', error)
    const errorMessage =
      error instanceof Error ? error.message : 'Unknown error'
    return NextResponse.json({ error: errorMessage }, { status: 500 })
  }
}

