'use client'

import { useState, useCallback, useEffect } from 'react'
import { usePhoneDevice } from './usePhoneDevice'
import type { CallParams, CallStatus, Store } from '@/types'

interface CustomerSession {
  customerId: string
  customerName: string
}

interface UseCustomerCallReturn {
  callStatus: CallStatus
  callSid: string | null
  currentStoreCode: string | null
  isReady: boolean
  error: string | null
  session: CustomerSession | null
  isLoading: boolean
  initializeDevice: () => Promise<void>
  makeCall: (store: Store, purpose: string, details: string) => Promise<void>
  hangUp: () => void
}

export function useCustomerCall(): UseCustomerCallReturn {
  const [session, setSession] = useState<CustomerSession | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [currentStoreCode, setCurrentStoreCode] = useState<string | null>(null)

  const {
    callStatus,
    callSid,
    isReady,
    error,
    initialize,
    makeCall: deviceMakeCall,
    hangUp,
  } = usePhoneDevice()

  useEffect(() => {
    const fetchSession = async () => {
      try {
        const res = await fetch('/api/session/customer')
        const data = await res.json()
        if (data.session) {
          setSession({
            customerId: data.session.customerId,
            customerName: data.session.customerName,
          })
        }
      } catch (err) {
        console.error('Failed to fetch session:', err)
      } finally {
        setIsLoading(false)
      }
    }

    fetchSession()
  }, [])

  const initializeDevice = useCallback(async () => {
    try {
      const res = await fetch('/api/token/customer', { method: 'POST' })
      const data = await res.json()

      if (!res.ok) {
        throw new Error(data.error || 'トークンの取得に失敗しました')
      }

      await initialize(data.token)
    } catch (err) {
      console.error('Failed to initialize device:', err)
      throw err
    }
  }, [initialize])

  const makeCall = useCallback(
    async (store: Store, purpose: string, details: string) => {
      if (!session) {
        throw new Error('ログインが必要です')
      }

      const params: Record<string, string> = {
        storeCode: store.code,
        customerId: session.customerId,
        customerName: session.customerName,
        purpose,
        details,
      }

      setCurrentStoreCode(store.code)
      await deviceMakeCall(params)
    },
    [session, deviceMakeCall]
  )

  return {
    callStatus,
    callSid,
    currentStoreCode,
    isReady,
    error,
    session,
    isLoading,
    initializeDevice,
    makeCall,
    hangUp,
  }
}

'use client'

import { useState, useCallback, useEffect } from 'react'
import { Call } from '@twilio/voice-sdk'
import { usePhoneDevice } from './usePhoneDevice'
import type { CallStatus, CallPurpose } from '@/types'

interface StaffSession {
  staffId: string
  staffName: string
  storeId: string
  storeCode: string
  storeName: string
}

interface IncomingCallInfo {
  customerId: string
  customerName: string
  purpose: CallPurpose
  details: string
  parentCallSid: string | null
}

interface UseStaffReceptionReturn {
  callStatus: CallStatus
  callSid: string | null
  isReady: boolean
  error: string | null
  session: StaffSession | null
  isLoading: boolean
  incomingCallInfo: IncomingCallInfo | null
  initializeDevice: () => Promise<void>
  acceptCall: () => void
  rejectCall: () => void
  hangUp: () => void
}

export function useStaffReception(): UseStaffReceptionReturn {
  const [session, setSession] = useState<StaffSession | null>(null)
  const [isLoading, setIsLoading] = useState(true)
  const [incomingCallInfo, setIncomingCallInfo] =
    useState<IncomingCallInfo | null>(null)

  const handleIncomingCall = useCallback((call: Call) => {
    const params = call.customParameters

    const info: IncomingCallInfo = {
      customerId: params.get('customerId') || 'unknown',
      customerName: params.get('customerName') || '不明',
      purpose: (params.get('purpose') as CallPurpose) || 'other',
      details: params.get('details') || '',
      parentCallSid: params.get('parentCallSid') || null,
    }

    setIncomingCallInfo(info)
  }, [])

  const handleCallDisconnected = useCallback(() => {
    setIncomingCallInfo(null)
  }, [])

  const {
    callStatus,
    callSid,
    isReady,
    error,
    initialize,
