import { NextRequest, NextResponse } from 'next/server'
import { v4 as uuidv4 } from 'uuid'
import {
  createSession,
  addMessage,
  updateMessageText,
  endSession,
  getSession,
} from '@/lib/transcription/sync-store'
import type {
  TranscriptionTrack,
  TranscriptionMessage,
} from '@/types/transcription'

export async function POST(request: NextRequest): Promise<NextResponse> {
  try {
    const formData = await request.formData()
    const params = Object.fromEntries(formData.entries()) as Record<
      string,
      string
    >

    console.log('TRANSCRIPTION WEBHOOK received:', {
      status: params.TranscriptionStatus,
      callSid: params.CallSid,
      transcriptionSid: params.TranscriptionSid,
      text: params.TranscriptionData?.slice(0, 50),
    })

    const callSid = params.CallSid
    const transcriptionSid = params.TranscriptionSid
    const status = params.TranscriptionStatus

    if (!callSid || !transcriptionSid) {
      console.log('TRANSCRIPTION WEBHOOK: Missing required parameters')
      return NextResponse.json(
        { error: 'Missing required parameters' },
        { status: 400 }
      )
    }

    switch (status) {
      case 'started':
        await handleStarted(callSid, transcriptionSid)
        break

      case 'in-progress':
        await handleContent(callSid, params)
        break

      case 'stopped':
        await handleStopped(callSid)
        break

      case 'error':
        await handleError(callSid, params.ErrorMessage)
        break

      default:
        break
    }

    return NextResponse.json({ success: true })
  } catch (error) {
    console.error('TRANSCRIPTION WEBHOOK error:', error)
    const errorMessage =
      error instanceof Error ? error.message : 'Unknown error'
    return NextResponse.json({ error: errorMessage }, { status: 500 })
  }
}

async function handleStarted(
  callSid: string,
  transcriptionSid: string
): Promise<void> {
  await createSession(callSid, transcriptionSid)
}

async function handleContent(
  callSid: string,
  params: Record<string, string>
): Promise<void> {
  const text = params.TranscriptionData
  const track = params.Track as TranscriptionTrack
  const isFinal = params.Final === 'true'
  const sequenceId = params.SequenceId

  if (!text || !track) {
    return
  }

  const session = await getSession(callSid)
  if (!session) {
    await createSession(callSid, params.TranscriptionSid || 'unknown')
  }

  const currentSession = session || (await getSession(callSid))
  if (!currentSession) {
    return
  }

  const existingMessageIndex = currentSession.messages.findIndex(
    (msg) => msg.id.startsWith(`${sequenceId}-${track}`) && !msg.isFinal
  )

  if (existingMessageIndex >= 0 && !isFinal) {
    const existingMessage = currentSession.messages[existingMessageIndex]
    await updateMessageText(callSid, existingMessage.id, text, isFinal)
  } else {
    const message: TranscriptionMessage = {
      id: `${sequenceId}-${track}-${uuidv4().slice(0, 8)}`,
      callSid,
      track,
      text,
      timestamp: Date.now(),
      isFinal,
    }
    await addMessage(callSid, message)
  }
}

async function handleStopped(callSid: string): Promise<void> {
  await endSession(callSid, 'stopped')
}

async function handleError(
  callSid: string,
  errorMessage?: string
): Promise<void> {
  if (errorMessage) {
    console.error('Transcription error:', errorMessage)
  }
  await endSession(callSid, 'error')
}

