'use client'

import { useEffect, useRef } from 'react'
import type { TranscriptionMessage } from '@/types/transcription'
import { TranscriptionBubble } from './TranscriptionBubble'

interface TranscriptionChatProps {
  messages: TranscriptionMessage[]
  isCustomerView: boolean
  isConnected: boolean
}

export function TranscriptionChat({
  messages,
  isCustomerView,
  isConnected,
}: TranscriptionChatProps) {
  const scrollRef = useRef<HTMLDivElement>(null)
  const containerRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollIntoView({ behavior: 'smooth' })
    }
  }, [messages])

  return (
    <div className="flex flex-col h-full bg-gray-50 rounded-lg overflow-hidden">
      <div className="flex items-center justify-between px-4 py-3 bg-green-600 text-white">
        <div className="flex items-center gap-2">
          <div className="w-2 h-2 rounded-full bg-white animate-pulse" />
          <span className="font-medium text-sm">通話文字起こし</span>
        </div>
        <span className="text-xs opacity-80">
          {isConnected ? 'リアルタイム' : '待機中'}
        </span>
      </div>

      <div
        ref={containerRef}
        className="flex-1 overflow-y-auto p-4 space-y-1"
        style={{ minHeight: '300px', maxHeight: '400px' }}
      >
        {messages.length === 0 ? (
          <div className="flex items-center justify-center h-full text-gray-400 text-sm">
            <div className="text-center">
              <div className="mb-2">💬</div>
              <p>通話が開始されると</p>
              <p>文字起こしが表示されます</p>
            </div>
          </div>
        ) : (
          <>
            {messages.map((message) => (
              <TranscriptionBubble
                key={message.id}
                message={message}
                isCustomerView={isCustomerView}
              />
            ))}
            <div ref={scrollRef} />
          </>
        )}
      </div>

      <div className="px-4 py-2 bg-white border-t border-gray-100">
        <div className="flex items-center justify-center gap-2 text-xs text-gray-400">
          <span className="w-1.5 h-1.5 rounded-full bg-green-500" />
          <span>音声認識による自動文字起こし</span>
        </div>
      </div>
    </div>
  )
}

'use client'

import type { TranscriptionMessage } from '@/types/transcription'

interface TranscriptionBubbleProps {
  message: TranscriptionMessage
  isCustomerView: boolean
}

export function TranscriptionBubble({
  message,
  isCustomerView,
}: TranscriptionBubbleProps) {
  const isFromMe =
    (isCustomerView && message.track === 'inbound_track') ||
    (!isCustomerView && message.track === 'outbound_track')

  const time = new Date(message.timestamp).toLocaleTimeString('ja-JP', {
    hour: '2-digit',
    minute: '2-digit',
  })

  return (
    <div
      className={`flex ${isFromMe ? 'justify-end' : 'justify-start'} mb-3`}
    >
      <div
        className={`max-w-[75%] ${
          isFromMe
            ? 'order-2'
            : 'order-1'
        }`}
      >
        <div
          className={`px-4 py-2 rounded-2xl ${
            isFromMe
              ? 'bg-green-500 text-white rounded-br-sm'
              : 'bg-white text-gray-800 rounded-bl-sm shadow-sm border border-gray-100'
          } ${!message.isFinal ? 'opacity-70' : ''}`}
        >
          <p className="text-sm leading-relaxed whitespace-pre-wrap break-words">
            {message.text}
            {!message.isFinal && (
              <span className="inline-block ml-1 text-xs opacity-60">...</span>
            )}
          </p>
        </div>
        <div
          className={`flex items-center gap-1 mt-1 text-xs text-gray-400 ${
            isFromMe ? 'justify-end' : 'justify-start'
          }`}
        >
          <span>{time}</span>
          {!message.isFinal && (
            <span className="text-blue-400">入力中</span>
          )}
        </div>
      </div>
    </div>
  )
}

