  TranscriptionMessage,
} from '@/types/transcription'

export async function POST(request: NextRequest): Promise<NextResponse> {
  try {
    const formData = await request.formData()
    const params = Object.fromEntries(formData.entries()) as Record<
      string,
      string
    >

    console.log('TRANSCRIPTION WEBHOOK received:', JSON.stringify(params))

    const callSid = params.CallSid
    const transcriptionSid = params.TranscriptionSid
    const transcriptionEvent = params.TranscriptionEvent

    // Handle transcription-started event
    if (transcriptionEvent === 'transcription-started') {
      console.log('Transcription started for call:', callSid)
      if (callSid && transcriptionSid) {
        await createSession(callSid, transcriptionSid)
      }
      return NextResponse.json({ success: true })
    }

    // Handle transcription-stopped event
    if (transcriptionEvent === 'transcription-stopped') {
      console.log('Transcription stopped for call:', callSid)
      if (callSid) {
        await endSession(callSid, 'stopped')
      }
      return NextResponse.json({ success: true })
    }

    // Handle text content
    // Try multiple field names for text
    let text =
      params.TranscriptionText ||
      params.TranscriptionData ||
      params.transcriptionText

    // Parse TranscriptionData if it's JSON
    if (!text && params.TranscriptionData) {
      try {
        const parsed = JSON.parse(params.TranscriptionData)
        text = parsed.transcript || parsed.text
      } catch {
        // Not JSON, use as is
        text = params.TranscriptionData
      }
    }

    const track = (params.Track || params.trackLabel || 'unknown') as TranscriptionTrack
    const sequenceId = params.SequenceId || Date.now().toString()
    const isFinal = params.Final === 'true' || params.final === 'true'

    if (!callSid || !text) {
      console.log('Missing callSid or text:', { callSid, text })
      return NextResponse.json({ success: true })
    }

    // Ensure session exists
    let session = await getSession(callSid)
    if (!session) {
      await createSession(callSid, transcriptionSid || 'unknown')
      session = await getSession(callSid)
    }

    if (!session) {
      console.error('Failed to create session for:', callSid)
      return NextResponse.json({ success: false })
    }

    // Check for existing message to update
    const existingMessageIndex = session.messages.findIndex(
      (msg) => msg.id.startsWith(`${sequenceId}-${track}`) && !msg.isFinal
    )

    if (existingMessageIndex >= 0 && !isFinal) {
      const existingMessage = session.messages[existingMessageIndex]
      await updateMessageText(callSid, existingMessage.id, text, isFinal)
    } else {
      const message: TranscriptionMessage = {
        id: `${sequenceId}-${track}-${uuidv4().slice(0, 8)}`,
        callSid,
        track,
        text,
        timestamp: Date.now(),
        isFinal,
      }
      await addMessage(callSid, message)
    }

    return NextResponse.json({ success: true })
  } catch (error) {
    console.error('TRANSCRIPTION WEBHOOK error:', error)
    const errorMessage =
      error instanceof Error ? error.message : 'Unknown error'
    return NextResponse.json({ error: errorMessage }, { status: 500 })
  }
}

